function IS_EVEN_FORM(G):
    n <- dimension(G)
    assert G is symmetric            # G[i][j] == G[j][i] for all i,j
    for i in 0 .. n-1:
        if G[i][i] mod 2 != 0:
            return False             # odd diagonal entry => odd form
    return True                      # all diagonal entries even => even form

