function INTEGER_DETERMINANT(G):
    A <- copy of G as exact fractions;  det <- 1
    for col in 0 .. n-1:
        find pivot row r >= col with A[r][col] != 0
        if none: return 0
        if r != col: swap rows; det <- -det
        det <- det * A[col][col]
        for r in col+1 .. n-1:
            f <- A[r][col] / A[col][col]
            A[r] <- A[r] - f * A[col]
    return integer(det)

function IS_UNIMODULAR(G):
    return INTEGER_DETERMINANT(G) in {+1, -1}

